import docx, glob, os
kws = ['northline','ashford','pre-app','pre application','preapplication','case track','case log','case no','case #','case id','case-id','elderpine','aln-108','tracking']
print('===== DOCX FILES =====')
for f in sorted(glob.glob('**/*.docx', recursive=True)):
    try:
        d = docx.Document(f)
    except Exception as e:
        print(f,'ERR',e); continue
    txt=[]
    for p in d.paragraphs: txt.append(p.text)
    for t in d.tables:
        for r in t.rows:
            for c in r.cells: txt.append(c.text)
    full='\n'.join(txt)
    low=full.lower()
    hits=[k for k in kws if k in low]
    print('='*70)
    print('DOCX:',f,'| HITS:',hits)
    if hits:
        # print matching lines
        for line in full.splitlines():
            if any(k in line.lower() for k in kws):
                print('   >',line[:300])
"

